+/**
+ * SVG sanitizer to prevent XSS attacks
+ * Removes script elements and dangerous event handlers
+ */
+function sanitizeSVG(svgContent) {
+  // Remove script elements and their contents
+  let sanitized = svgContent.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '');
+  
+  // Remove event handlers (onload, onerror, onclick, etc.)
+  sanitized = sanitized.replace(
+    /\s(on\w+)\s*=\s*(["'][^"']*["']|{[^}]*})/gi,
+    ''
+  );
+  
+  // Remove JavaScript URLs
+  sanitized = sanitized.replace(
+    /\s(xlink:href|href)\s*=\s*["']\s*javascript:/gi,
+    (match, attr) => ` ${attr}=""`
+  );
+  
+  // Remove <object> and <iframe> elements which can be used for XSS
+  sanitized = sanitized.replace(/<object\b[^>]*>.*?<\/object>/gi, '');
+  sanitized = sanitized.replace(/<iframe\b[^>]*>.*?<\/iframe>/gi, '');
+  
+  return sanitized;
+}
+
+module.exports = {
+  sanitizeSVG
+};

