+// Safe regex validation to prevent ReDoS attacks
+// Based on known dangerous regex patterns and complexity analysis
+
+export function safeRegex(pattern: string): boolean {
+  if (typeof pattern !== "string") return false
+  
+  // Check for exponential backtracking patterns
+  const dangerousPatterns = [
+    /\([^)]*\*[^)]*\)/, // Nested quantifiers inside groups
+    /\([^)]*\+[^)]*\)/, // Nested + quantifiers
+    /\([^)]*\?[^)]*\)/, // Nested ? quantifiers
+    /\([^)]*\{[^}]*,[^}]*\}[^)]*\)/, // Nested range quantifiers
+  ]
+  
+  for (const dangerousPattern of dangerousPatterns) {
+    if (dangerousPattern.test(pattern)) {
+      return false
+    }
+  }
+  
+  // Check for exponential backtracking in alternations
+  if (pattern.includes("|")) {
+    const parts = pattern.split("|")
+    // Check if any alternation part could match a prefix of another
+    for (let i = 0; i < parts.length; i++) {
+      for (let j = 0; j < parts.length; j++) {
+        if (i !== j && parts[j].startsWith(parts[i])) {
+          return false
+        }
+      }
+    }
+  }
+  
+  // Additional safety: limit pattern length to prevent complex patterns
+  if (pattern.length > 1000) {
+    return false
+  }
+  
+  return true
+}

