+/**
+ * Parse and validate Content-Type header to prevent header injection attacks
+ * Returns the normalized content type or empty string if invalid
+ */
+export function parseContentType(contentType: string): string {
+  if (!contentType) {
+    return '';
+  }
+  
+  // Split by semicolon to handle parameters like charset
+  const parts = contentType.split(';');
+  const mimeType = parts[0].trim().toLowerCase();
+  
+  // Validate that it's a simple MIME type without multiple values
+  if (mimeType.includes(',') || !/^[a-z]+\/[a-z0-9\-\+\.]+$/.test(mimeType)) {
+    return '';
+  }
+  
+  return mimeType;
+}

