+/**
+ * Host validation utility to prevent SSRF attacks
+ */
+
+// List of blocked IP ranges and hosts
+const BLOCKED_SUBNETS = [
+  '127.0.0.0/8',      // IPv4 loopback
+  '10.0.0.0/8',       // Private network
+  '172.16.0.0/12',    // Private network
+  '192.168.0.0/16',   // Private network
+  '169.254.0.0/16',   // Link-local
+  '::1/128',          // IPv6 loopback
+  'fc00::/7',         // IPv6 private network
+  'fe80::/10',        // IPv6 link-local
+];
+
+// Specific sensitive hosts to block
+const BLOCKED_HOSTS = [
+  'metadata.google.internal',
+  'metadata.google.internal.',
+  '169.254.169.254',  // AWS metadata service
+  'metadata.tencentyun.com',
+];
+
+export function isAllowedHost(host: string): boolean {
+  try {
+    const url = new URL(host.startsWith('http') ? host : `https://${host}`);
+    const hostname = url.hostname;
+    
+    // Check against blocked hosts and subnets
+    return !BLOCKED_HOSTS.includes(hostname) && 
+           !isInBlockedSubnet(hostname);
+  } catch {
+    return false; // Invalid URL format
+  }
+}
+
+function isInBlockedSubnet(ip: string): boolean {
+  // Implementation of IP subnet checking
+  // This would use a library like ip-address or similar
+  // For minimal patch, we'll implement basic check
+  for (const subnet of BLOCKED_SUBNETS) {
+    if (subnet.startsWith('127.') && ip.startsWith('127.')) return true;
+    if (subnet.startsWith('10.') && ip.startsWith('10.')) return true;
+    if (subnet.startsWith('192.168.') && ip.startsWith('192.168.')) return true;
+    if (subnet.startsWith('169.254.') && ip.startsWith('169.254.')) return true;
+    if (subnet.startsWith('172.')) {
+      const secondOctet = parseInt(ip.split('.')[1]);
+      if (secondOctet >= 16 && secondOctet <= 31) return true;
+    }
+  }
+  return false;
+}

