+/**
+ * Validate if a URL is safe for use in anchor elements
+ * Blocks dangerous protocols that could lead to XSS or other attacks
+ */
+export function isSafeUrl(url: string): boolean {
+  try {
+    const parsed = new URL(url, window.location.href)
+    const unsafeProtocols = ['javascript:', 'data:', 'file:', 'vbscript:']
+    return !unsafeProtocols.includes(parsed.protocol.toLowerCase())
+  } catch {
+    // If URL parsing fails, it might be a relative URL or malformed
+    // Allow relative URLs but block any that start with dangerous protocols
+    return !/^\s*(javascript:|data:|file:|vbscript:)/i.test(url)
+  }
+}

