+/**
+ * Validates redirect URLs to prevent open redirect vulnerabilities
+ * @param {string} url - The redirect URL to validate
+ * @returns {boolean} - True if the URL is safe for redirection
+ */
+export function isValidRedirect(url) {
+  if (!url || typeof url !== 'string') {
+    return false;
+  }
+  
+  // Allow relative URLs (safe)
+  if (url.startsWith('/') && !url.startsWith('//')) {
+    // Ensure it's a proper relative path without protocol-relative URLs
+    return true;
+  }
+  
+  try {
+    const parsedUrl = new URL(url, window.location.origin);
+    
+    // Allow same-origin URLs
+    if (parsedUrl.origin === window.location.origin) {
+      return true;
+    }
+    
+    // Optionally: Add whitelisted domains here if needed
+    // const allowedDomains = ['trusted.example.com'];
+    // if (allowedDomains.includes(parsedUrl.hostname)) {
+    //   return true;
+    // }
+    
+    return false;
+  } catch (error) {
+    // Invalid URL format
+    return false;
+  }
+}

