+import * as path from 'path';
+
+/**
+ * Sanitizes a file path to prevent directory traversal attacks
+ * @param filePath The file path to sanitize
+ * @returns The sanitized file path
+ */
+export const sanitizePath = (filePath: string): string => {
+  if (!filePath || typeof filePath !== 'string') {
+    return '';
+  }
+
+  // Normalize the path to resolve '..' and '.' segments
+  const normalizedPath = path.normalize(filePath);
+  
+  // Remove any null bytes (common in path traversal attacks)
+  const cleanPath = normalizedPath.replace(/\0/g, '');
+  
+  // Resolve the path relative to root to prevent absolute paths
+  const resolvedPath = path.resolve('/', cleanPath).substring(1);
+  
+  // Check for directory traversal attempts
+  if (cleanPath.includes('..') || path.isAbsolute(cleanPath)) {
+    // Return only the basename if traversal is detected
+    return path.basename(cleanPath);
+  }
+  
+  // Return the sanitized path
+  return resolvedPath;
+};

