+import type { NextRequest } from 'next/server'
+
+/**
+ * Verify if the request has access to view flags
+ * This prevents unauthorized access to the flags discovery endpoint
+ */
+export async function verifyAccess(request: NextRequest): Promise<boolean> {
+  // Check for API key in authorization header
+  const authHeader = request.headers.get('authorization')
+  if (authHeader?.startsWith('Bearer ')) {
+    const apiKey = authHeader.substring(7)
+    const validApiKey = process.env.FLAGS_API_KEY
+    
+    if (validApiKey && apiKey === validApiKey) {
+      return true
+    }
+  }
+  
+  // Optionally check for other authentication methods
+  // For example, session-based authentication for authenticated users
+  // const session = await getSession(request)
+  // return session?.user !== undefined
+  
+  return false
+}

