+export function isSafeContentType(contentType: string): boolean {
+  if (!contentType || typeof contentType !== 'string') {
+    return false;
+  }
+
+  const normalizedType = contentType.toLowerCase().trim();
+  
+  // Block content types that could potentially execute code
+  const dangerousPatterns = [
+    /application\/x-javascript/i,
+    /application\/x-httpd-php/i,
+    /application\/x-asp/i,
+    /application\/x-aspx/i,
+    /application\/x-jsp/i,
+    /text\/html/i,
+    /text\/javascript/i,
+    /text\/x-javascript/i,
+    /text\/x-httpd-php/i,
+    /text\/x-asp/i,
+    /text\/x-aspx/i,
+    /text\/x-jsp/i,
+    /.*script.*/i,
+    /.*exec.*/i,
+    /.*eval.*/i,
+    /.*system.*/i,
+    /.*shell.*/i,
+    /.*command.*/i,
+  ];
+
+  // Check for dangerous patterns
+  for (const pattern of dangerousPatterns) {
+    if (pattern.test(normalizedType)) {
+      return false;
+    }
+  }
+
+  // Allow common safe content types
+  const safePatterns = [
+    /^application\/json($|;)/i,
+    /^application\/xml($|;)/i,
+    /^text\/plain($|;)/i,
+    /^multipart\/form-data($|;)/i,
+    /^application\/x-www-form-urlencoded($|;)/i,
+  ];
+
+  // If it matches a safe pattern, allow it
+  for (const pattern of safePatterns) {
+    if (pattern.test(normalizedType)) {
+      return true;
+    }
+  }
+
+  // For unknown types, be conservative and reject
+  return false;
