+ * @param url The URL to check.
+ * @param allowPrivateAddresses Optional list of private IP addresses to allow.
+ * @returns True if the URL is safe to fetch from, false otherwise.
+ */
+export function isSafeUrl(
+  url: string,
+  allowPrivateAddresses: string[] = []
+): boolean {
+  try {
+    const parsed = new URL(url);
+
+    // Require a hostname
+    if (!parsed.hostname) return false;
+
+    // Only allow HTTP and HTTPS protocols
+    if (!["http:", "https:"].includes(parsed.protocol)) return false;
+
+    // Check for localhost/loopback
+    if (parsed.hostname === "localhost" || parsed.hostname === "127.0.0.1") {
+      return allowPrivateAddresses.includes(parsed.hostname);
+    }
+
+    // Check for IPv4 addresses
+    if (/^\d+\.\d+\.\d+\.\d+$/.test(parsed.hostname)) {
+      const ip = parsed.hostname;
+      // Check if it's a private IP address
+      if (
+        ip.startsWith("10.") ||
+        ip.startsWith("172.") && parseInt(ip.split(".")[1]) >= 16 && parseInt(ip.split(".")[1]) <= 31 ||
+        ip.startsWith("192.168.")
+      ) {
+        return allowPrivateAddresses.includes(ip);
+      }
+    }
+
+    // Check for IPv6 addresses (simplified check for private ranges)
+    if (parsed.hostname.startsWith("[") && parsed.hostname.includes("]")) {
+      const ip = parsed.hostname.slice(1, parsed.hostname.indexOf("]"));
+      // Check for IPv6 loopback ::1
+      if (ip === "::1") {
+        return allowPrivateAddresses.includes(ip);
+      }
+      // Check for IPv6 private ranges (fc00::/7)
+      if (ip.startsWith("fc") || ip.startsWith("fd")) {
+        return allowPrivateAddresses.includes(ip);
+      }
+    }
+
+    // Check for dangerous protocols disguised in the hostname
+    if (parsed.hostname.includes(":")) {
+      // This could indicate a protocol embedded in hostname
+      return false;
+    }
+
+    // Check for file/data URIs disguised as HTTP
+    if (parsed.hostname.includes("file") || parsed.hostname.includes("data")) {
+      return false;
+    }
+
+    return true;
+  } catch {
+    // Invalid URL
+    return false;
+  }
+}

