+const { URL } = require('url');
+const config = require('@/config').value;
+
+const isPrivateIP = (ip) => {
+    if (ip === 'localhost' || ip === '127.0.0.1' || ip === '::1') {
+        return true;
+    }
+
+    // Check for private IP ranges (RFC 1918, RFC 4193, etc.)
+    const parts = ip.split('.').map(Number);
+    if (parts.length === 4) {
+        return (
+            parts[0] === 10 ||
+            (parts[0] === 172 && parts[1] >= 16 && parts[1] <= 31) ||
+            (parts[0] === 192 && parts[1] === 168) ||
+            parts[0] === 127 ||
+            (parts[0] === 169 && parts[1] === 254)
+        );
+    }
+
+    return false;
+};
+
+const validateUrl = (url) => {
+    try {
+        const parsed = new URL(url);
+        
+        // Block private IPs
+        if (isPrivateIP(parsed.hostname)) {
+            throw new Error('Access to private IP is not allowed');
+        }
+        
+        // Block localhost variants
+        if (parsed.hostname.endsWith('.localhost') || parsed.hostname.endsWith('.local')) {
+            throw new Error('Access to local domains is not allowed');
+        }
+        
+        return parsed;
+    } catch (error) {
+        throw new Error(`Invalid URL: ${error.message}`);
+    }
+};
+
+module.exports = { validateUrl };
