@@ -0,0 +1,42 @@
+import type { ServerRequest } from './types';
+import { randomBytes } from 'crypto';
+
+/**
+ * CSRF token storage interface
+ */
+interface CSRFTokenStore {
+  getToken(): Promise<string>;
+  validateToken(token: string): Promise<boolean>;
+}
+
+/**
+ * Default CSRF token implementation using session storage
+ */
+class DefaultCSRFTokenStore implements CSRFTokenStore {
+  private tokens = new Map<string, string>();
+
+  async getToken(): Promise<string> {
+    const token = randomBytes(32).toString('hex');
+    const id = randomBytes(16).toString('hex');
+    this.tokens.set(id, token);
+    // Set expiration (1 hour)
+    setTimeout(() => this.tokens.delete(id), 3600000);
+    return `${id}:${token}`;
+  }
+
+  async validateToken(token: string): Promise<boolean> {
+    const [id, actualToken] = token.split(':');
+    if (!id || !actualToken) return false;
+    
+    const storedToken = this.tokens.get(id);
+    if (!storedToken) return false;
+    
+    this.tokens.delete(id); // Use once
+    return storedToken === actualToken;
+  }
+}
+
+export const csrfTokenStore = new DefaultCSRFTokenStore();
+export const verifyCSRFToken = async (token: string, request: ServerRequest): Promise<boolean> => {
+  return await csrfTokenStore.validateToken(token);
+};
