+/**
+ * Sanitize HTML content to prevent XSS attacks
+ * @param {string} html - HTML string to sanitize
+ * @returns {string} Sanitized HTML string
+ */
+export function sanitizeHTML(html) {
+  if (!html || typeof html !== 'string') {
+    return html;
+  }
+  
+  const div = document.createElement('div');
+  div.textContent = html;
+  
+  // Allow basic formatting tags but strip scripts and event handlers
+  const allowedTags = /<\/?(b|i|u|em|strong|span|div|p|br|hr|ul|ol|li|table|tr|td|th)(\s[^>]*)?>/gi;
+  const sanitized = div.innerHTML.replace(allowedTags, (match) => {
+    return match.replace(/on\w+\s*=\s*["'][^"']*["']/gi, ''); // Remove event handlers
+  });
+  return sanitized;
+}

