+/**
+ * CSRF protection middleware for mutating HTTP methods
+ * Rejects non-loopback origins for state-changing operations
+ */
+
+const LOOPBACK_IPS = new Set(['127.0.0.1', '::1', 'localhost']);
+const MUTATING_METHODS = new Set(['POST', 'PUT', 'PATCH', 'DELETE']);
+
+/**
+ * Check if a hostname or IP is a loopback address
+ * @param {string} host - Hostname or IP to check
+ * @returns {boolean} True if loopback
+ */
+function isLoopback(host) {
+    if (!host) return false;
+    
+    // Remove port if present
+    const hostname = host.split(':')[0];
+    
+    // Check against loopback IPs and localhost
+    if (LOOPBACK_IPS.has(hostname.toLowerCase())) {
+        return true;
+    }
+    
+    // Check for IPv4 loopback range (127.0.0.0/8)
+    if (hostname.startsWith('127.')) {
+        const parts = hostname.split('.');
+        if (parts.length === 4 && parts[0] === '127') {
+            return true;
+        }
+    }
+    
+    return false;
+}
+
+/**
+ * CSRF protection middleware
+ */
+function csrfProtection(req, res, next) {
+    // Only apply to mutating methods
+    if (!MUTATING_METHODS.has(req.method)) {
+        return next();
+    }
+    
+    // Check Origin header first, then Referer, then Sec-Fetch-Site
+    const origin = req.get('Origin');
+    const referer = req.get('Referer');
+    const secFetchSite = req.get('Sec-Fetch-Site');
+    
+    // Reject if Sec-Fetch-Site indicates cross-site
+    if (secFetchSite === 'cross-site') {
+        return res.status(403).json({ error: 'Cross-site requests not allowed for mutating operations' });
+    }
+    
+    // Parse host from Origin or Referer
+    let requestHost = null;
+    
+    if (origin && origin !== 'null') {
+        try {
+            const url = new URL(origin);
+            requestHost = url.hostname;
+        } catch (e) {
+            // Invalid URL, treat as non-loopback
+        }
+    }
+    
+    if (!requestHost && referer) {
+        try {
+            const url = new URL(referer);
+            requestHost = url.hostname;
+        } catch (e) {
+            // Invalid URL, treat as non-loopback
+        }
+    }
+    
+    // If we can determine the host and it's not loopback, reject
+    if (requestHost && !isLoopback(requestHost)) {
+        return res.status(403).json({ error: 'Mutating operations only allowed from loopback origins' });
+    }
+    
+    // Allow the request
+    next();
+}
+
+module.exports = { csrfProtection, isLoopback };
