+/**
+ * Sanitize HTML string to prevent XSS
+ * @param {string} str HTML string to sanitize
+ * @returns {string} Sanitized HTML string
+ */
+export function sanitize(str) {
+	if (typeof str !== "string") {
+		return str;
+	}
+	
+	const div = document.createElement("div");
+	div.textContent = str;
+	return div.innerHTML;
+}
+
+/**
+ * Sanitize object properties that may contain HTML
+ * @param {Object} obj Object to sanitize
+ * @param {Array<string>} properties Property names to sanitize
+ * @returns {Object} Sanitized object
+ */
+export function sanitizeObject(obj, properties) {
+	if (!obj || typeof obj !== "object") {
+		return obj;
+	}
+	
+	const result = { ...obj };
+	properties.forEach(prop => {
+		if (result[prop] && typeof result[prop] === "string") {
+			result[prop] = sanitize(result[prop]);
+		}
+	});
+	return result;
+}
+
+/**
+ * Check if value needs sanitization
+ * @param {*} value Value to check
+ * @returns {boolean} True if value is a string that may contain HTML
+ */
+export function needsSanitization(value) {
+	return typeof value === "string" && 
+		(/<[^>]*>/.test(value) || /[&<>"'`]/.test(value));
+}

