+/**
+ * Validate URLs for prerendering to prevent SSRF and DoS attacks
+ * @param {string} url
+ * @returns {boolean}
+ */
+export function is_valid_prerender_url(url) {
+	if (!url || typeof url !== 'string') {
+		return false;
+	}
+
+	// Prevent SSRF by disallowing URLs with protocol schemes
+	if (url.includes('://')) {
+		return false;
+	}
+
+	// Prevent directory traversal attacks
+	if (url.includes('../') || url.includes('..\\')) {
+		return false;
+	}
+
+	// Limit URL length to prevent resource exhaustion
+	if (url.length > 2048) {
+		return false;
+	}
+
+	// Ensure URL only contains safe characters
+	const safe_pattern = /^[a-zA-Z0-9\-._~!$&'()*+,;=:@/\s%]*$/;
+	if (!safe_pattern.test(url)) {
+		return false;
+	}
+
+	return true;
+}
